def generate(rng, n):
    if n < 1:
        n = 1
    missing = rng.randint(0, n)
    nums = [i for i in range(n + 1) if i != missing]
    rng.shuffle(nums)
    return [nums]

def generate_worst(rng, n):
    if n < 1:
        n = 1
    nums = [i for i in range(n)]
    return [nums]

